"""Estimate additional station-keeping requirements caused bygeomagnetic storm related orbital decay.This does NOT measure actual fuel consumption yet.It estimates the extra orbital capacity needed tocompensate for the excess altitude loss seen during storms."""from pathlib import Pathimport numpy as npimport pandas as pd# PathsPROJECT_ROOT = Path(__file__).resolve().parent.parentPROCESSED_DATA_DIR = (    PROJECT_ROOT    / "data"    / "processed")RESULTS_DIR = (    PROJECT_ROOT    / "results")RESULTS_DIR.mkdir(    parents=True,    exist_ok=True,)DECAY_DATA_FILE = (    PROCESSED_DATA_DIR    / "daily_satellite_altitude_kp_decay.csv")STORM_RESULTS_FILE = (    RESULTS_DIR    / "storm_vs_quiet_decay.csv")OUTPUT_FILE = (    RESULTS_DIR    / "stationkeeping_delta_v.csv")# Physical constantsMU_EARTH = 3.986004418e14   # m^3 / s^2R_EARTH = 6.371e6           # m# SatellitesANALYSIS_SATELLITES = [    27651,    33591,    39444,]# Orbital physicsdef orbital_velocity(altitude_km):    """    Circular orbital velocity at a given altitude.    """    altitude_m = altitude_km * 1000.0    orbital_radius_m = (        R_EARTH        + altitude_m    )    velocity_ms = np.sqrt(        MU_EARTH        / orbital_radius_m    )    return velocity_msdef altitude_loss_to_delta_v(    altitude_km,    altitude_loss_km,):    """    Approximate delta-v needed to restore a small altitude loss.    For a nearly circular orbit:        delta_v ≈ (v / 2r) * delta_h    """    altitude_m = (        altitude_km        * 1000.0    )    delta_h_m = (        altitude_loss_km        * 1000.0    )    orbital_radius_m = (        R_EARTH        + altitude_m    )    velocity_ms = orbital_velocity(        altitude_km    )    delta_v_ms = (        velocity_ms        / (            2.0            * orbital_radius_m        )        * delta_h_m    )    return delta_v_ms# Load datadef load_data():    if not DECAY_DATA_FILE.exists():        raise FileNotFoundError(            f"\nCould not find:\n"            f"{DECAY_DATA_FILE}\n\n"            f"Run storm_decay_analysis.py first."        )    if not STORM_RESULTS_FILE.exists():        raise FileNotFoundError(            f"\nCould not find:\n"            f"{STORM_RESULTS_FILE}\n\n"            f"Run storm_decay_analysis.py first."        )    daily = pd.read_csv(        DECAY_DATA_FILE    )    storm_results = pd.read_csv(        STORM_RESULTS_FILE    )    daily["date"] = pd.to_datetime(        daily["date"],        errors="coerce",        utc=True,    )    return daily, storm_results# Analysisdef analyze_stationkeeping(    daily,    storm_results,):    results = []    for norad_id in ANALYSIS_SATELLITES:        satellite = (            daily[                daily["norad_id"]                == norad_id            ]            .dropna(                subset=[                    "daily_median_altitude_km",                    "orbital_decay_km_day",                    "daily_max_kp",                ]            )            .copy()        )        if satellite.empty:            print(                f"No daily data for "                f"NORAD {norad_id}."            )            continue        satellite_results = (            storm_results[                storm_results["norad_id"]                == norad_id            ]        )        if satellite_results.empty:            print(                f"No storm-decay results for "                f"NORAD {norad_id}."            )            continue             # Mean orbital altitude         mean_altitude_km = (            satellite[                "daily_median_altitude_km"            ]            .mean()        )           # Storm vs quiet decay               storm_decay_km_day = float(            satellite_results.iloc[0][                "storm_mean_decay_km_day"            ]        )        quiet_decay_km_day = float(            satellite_results.iloc[0][                "quiet_mean_decay_km_day"            ]        )        extra_decay_km_day = (            storm_decay_km_day            - quiet_decay_km_day        )        # Only positive excess decay creates           extra_decay_positive_km_day = max(            extra_decay_km_day,            0.0,        )           # Count storm days             storm_days = satellite[            satellite["storm_day"].astype(                str            ).str.lower()            == "true"        ]        n_storm_days = len(            storm_days        )              # Extra delta-v per storm day               extra_delta_v_per_storm_day_ms = (            altitude_loss_to_delta_v(                mean_altitude_km,                extra_decay_positive_km_day,            )        )               # Total excess altitude loss            total_excess_altitude_loss_km = (            extra_decay_positive_km_day            * n_storm_days        )             # Total extra delta-v               total_extra_delta_v_ms = (            altitude_loss_to_delta_v(                mean_altitude_km,                total_excess_altitude_loss_km,            )        )        start_date = (            satellite["date"].min()        )        end_date = (            satellite["date"].max()        )        observation_days = (            end_date            - start_date        ).days        observation_years = (            observation_days            / 365.25        )           if observation_years > 0:            observed_period_annualized_extra_delta_v_ms_year = (                total_extra_delta_v_ms                / observation_years            )        else:            observed_period_annualized_extra_delta_v_ms_year = np.nan              results.append(            {                "norad_id":                    norad_id,                "mean_altitude_km":                    mean_altitude_km,                "quiet_decay_km_day":                    quiet_decay_km_day,                "storm_decay_km_day":                    storm_decay_km_day,                "extra_decay_km_day":                    extra_decay_km_day,                "storm_days":                    n_storm_days,                "extra_delta_v_per_storm_day_ms":                    extra_delta_v_per_storm_day_ms,                "total_excess_altitude_loss_km":                    total_excess_altitude_loss_km,                "total_extra_delta_v_ms":                    total_extra_delta_v_ms,                "observation_years":                    observation_years,                "observed_period_annualized_extra_delta_v_ms_year":                    observed_period_annualized_extra_delta_v_ms_year,            }        )    results_df = pd.DataFrame(        results    )    return results_df# Maindef main():    daily, storm_results = load_data()    results = analyze_stationkeeping(        daily,        storm_results,    )    if results.empty:        print(            "\nNo station-keeping results "            "were produced."        )        return    results.to_csv(        OUTPUT_FILE,        index=False,    )    print(        "\nEstimated additional "        "station-keeping requirements:\n"    )    print(        results.to_string(            index=False        )    )    print(        f"\nResults saved to:\n"        f"{OUTPUT_FILE}"    )    print(        "\nNOTE:"        "\nThese values estimate the "        "equivalent delta-v needed to "        "compensate for excess storm-related "        "altitude loss."        "\nThey are NOT measurements of "        "actual spacecraft fuel consumption."    )if __name__ == "__main__":    main()